// Tipo para diligencia con todas las relaciones necesarias para Recibo
export type DiligenciaWithReciboRelations = Diligencia & {
  rol: RolCausa & {
    tribunal: Tribunal | null
    demanda: (Demanda & {
      abogados: Abogado & {
        banco: Banco | null
