    if (ejecutadoId) {
      ejecutado = ejecutados.find(e => e.id === ejecutadoId) ?? ejecutados[0] ?? null
    } else {
      ejecutado = ejecutados[0] ?? null
    }
  }
  
  // CarÃ¡tula: Banco / Ejecutado
  const caratula = [banco?.nombre, ejecutado?.nombre]
    .filter(Boolean)
    .join(' / ')
  
