        } else {
          console.log(`[PUT /api/demandas/${params.id}] âš ï¸ RolCausa not found for demandaId: ${params.id}`)
        }
      }

      return updatedDemanda
    })

    console.log(`[PUT /api/demandas/${params.id}] âœ… Demanda updated successfully:`, { id: result.id, rol: result.rol })

